\subsection{Sentence-level Layer}\label{sen_attn_model}
The sentence-level attention layer aims to discriminate various influences of sentences. When predicting candidate news $c^*$, sentences of news $c_i$ unequally affect user's choices. To implement this, we first represent sentences in a given piece of news $c_i$. The vector $\convec{s_{ij}}$ of sentence $s_{ij}$ is embedded in a $d$-dimensional space $\mathbb{R}^d$, and the vector $\convec{c_i} \in \mathbb{R}^{K \times d}$ of news $c_i$ is stacked by $\convec{s_{ij}}$, and the vector $\convec{c^*}\in\mathbb{R}^d$ of candidate news $c^*$ is calculated by averaging the sentences vectors.
Moreover, user identity information is learned by an embedding in a $d$-dimensional space, i.e., $\mathbf{u} \in\mathbb{R}^d$ for user $u$, which is randomly initialized and updated during training.

\begin{equation}\label{eq:sen_vec_1}
{\beta}_{i} = \frac{[\mathbf{u} \convec{{c}_{i}}\convec{{c}^*}]\mathbf{W}_1    \cdot (\mathbf{W}_2[\mathbf{u} \convec{{c}_{i}}\convec{{c}^*}]^T)}{\sqrt{d}},
\end{equation}

\begin{equation}\label{eq:sen_vec_1}
{\beta}_{i} = \frac{[\mathbf{u} \convec{{c}_{i}}\convec{{c}^*}]\mathbf{W}_1    \cdot (\mathbf{W}_2[\mathbf{u} \convec{{c}_{i}}\convec{{c}^*}]^T)}{\sqrt{d}},
\end{equation}

where $\mathbf{W}_{1}\in\mathbb{R}^{d\times d}$, $\mathbf{W}_{2} \in\mathbb{R}^{d \times d}$ are the parameters of model, $\cdot$ denotes the dot product operation,  $\sqrt{d}$ is a scale factor to prevent dot products growing large in magnitude, $\beta_i \in \mathbb{R}^{(K+2) \times (K+2)}$. Note that  
we omit the bias for brevity here.
These self attention weights are further normalized by softmax function, which can be interpreted as the content relevance among sentence $s_{ij}$ and candidate news $c^*$, user embedding $\mathbf{u}$.
With these weights, we compute the vector $\convec{c_i}$ of news $c_i$ with respect to candidate news ${c}^{*}$ as the dot product between ${\beta}_{i}$ and linearly transformed  $[\mathbf{u} \convec{{c}_{i}}\,\convec{{c}^*}]$ by model parameter $\mathbf{W_{3} \in \mathbb{R}^{d \times d}}$, that is, 
\begin{equation}
    \convec{{c}_{i}}= {\beta}_{i} \cdot  [\mathbf{u} \convec{{c}_{i}} \convec{{c}^*}] \mathbf{W_{3}} \in\mathbb{R}^{(K+2) \times d}
\end{equation}

\begin{equation} \label{eq:ele_vec_1}
\begin{aligned}
    q_{c_{i}}= [\mathbf{l}{c_i} \mathbf{l}{c^*}] \mathbf{W_{4}}, \\
    k_{c_{i}}= [\mathbf{l}{c_i} \mathbf{l}{c^*}] \mathbf{W_{5}}, \\
    v_{c_{i}}= [\mathbf{l}{c_i} \mathbf{l}{c^*}] \mathbf{W_{6}},
\end{aligned}
\end{equation}

\begin{equation} \label{eq:ele_vec_1}
\begin{aligned}
    q_{c_{i}}= [\mathbf{l}{c_i} \mathbf{l}{c^*}] \mathbf{W_{4}}, \\
    k_{c_{i}}= [\mathbf{l}{c_i} \mathbf{l}{c^*}] \mathbf{W_{5}}, \\
    v_{c_{i}}= [\mathbf{l}{c_i} \mathbf{l}{c^*}] \mathbf{W_{6}},
\end{aligned}
\end{equation}

where $\mathbf{W_{4}} \in \mathbb{R}^{2d \times d}$, $\mathbf{W_{5}} \in \mathbb{R}^{2d \times d}$ and $\mathbf{W_{6}} \in \mathbb{R}^{2d \times d}$ are model parameters, $q_{c_{i}}$, $ k_{c_{i}}$ and $v_{c_{i}}$ represent different linear transformations of $[\mathbf{l}{c_i} \mathbf{l}{c^*}]$, which will be used to compute self-attended vector representation.
To model the internal and external interactions among element vector of $c_i$ and $c^*$, we take dot product between $q_{c_i}$ and $k_{c_{i}}$ to get the raw self-attention scores:
\begin{equation} \label{eq:ele_vec_2}
    {\gamma}_{i}= \frac{q_{c_i} \cdot {k_{c_{i}}}^T}{\sqrt{d}} \in \mathbb{R}^{5 \times 5}, 
\end{equation}
where $\sqrt{d}$ is a scale factor, and the raw self-attention scores are normalized by softmax function to probabilities followed by a dropout operation on entire elements to attend to.

\end{equation}
where $\sqrt{d}$ is a scale factor, and the raw self-attention scores are normalized by softmax function to probabilities followed by a dropout operation on entire elements to attend to.
Here self-attention scores ${\gamma}_{i}$ can be interpreted as the relevance of elements under the influence of both historical news $c_i$ and candidate news $c^*$. With these weights, we compute the element vector $\elevec{c_i}$ of news $c_i$ as dot product between ${\gamma}_{i}$ and $v_{c_{i}}$: 
\begin{equation}
    \elevec{c_i} = {\gamma}_i \cdot v_{c_{i}} \in \mathbb{R}^{5 \times d}
\end{equation}

\noindent
$\bullet$ \textbf{Embed with $\mathbf{r_{\mathcal{C}}}$.}
Given a news sequence $\mathcal{C}$, its representation $\mathbf{x'}_{\mathcal{C}}$ is concatenated with its corresponding relative time interval embedding $\mathbf{r_{\mathcal{C}}}$ and candidate news representation $\mathbf{x^*}$ as  $\mathbf{z}_{\mathcal{C}} = [\mathbf{x'}_{\mathcal{C}} \mathbf{r_{\mathcal{C}}} \mathbf{x}^*] \in \mathbb{R}^{L \times 7d}$, where $\mathbf{x'}_{\mathcal{C}} = \{ \mathbf{x'}_{c_1}, \mathbf{x'}_{c_2}, ..., \mathbf{x'}_{c_L} \} \in \mathbb{R}^{L \times 3d}$. The time-aware representation of candidate news is $\mathbf{z^*} = \mathbf{x^*}$.

\noindent
$\bullet$ \textbf{Embed with $\mathbf{a_{\mathcal{C}}}$.}
History news representation and candidate news representation are concatenated with their corresponding absolute time embedding as $\mathbf{z}_{\mathcal{C}} = [\mathbf{x'}_{\mathcal{C}} \mathbf{a}_{\mathcal{C}}^{1:L}] \in \mathbb{R}^{L \times 4d}$, $\mathbf{z^*} = [\mathbf{x^*} \mathbf{a}_{\mathcal{C}}^{L+1}] \in \mathbb{R}^{4d}$, respectively.

The variables are firstly input into the self-attention layer,  and then a position-wise feed-forward layer is leveraged to process the output. At last, we use a fully connected layer and a residual connection layer to predict the final results:
\begin{equation} \label{eq:news_vec_1}
\begin{aligned}
        \mathbf{t}_{c_i} &= \text{Attention}(\mathbf{t}_{c_i}), \\
        \mathbf{x}_{c_i} &= \phi{(\mathbf{t}_{c_i} \cdot \mathbf{W_a})}, \\
        \mathbf{x}_{c_i} &= \text{LN}(\text{Dropout}(\mathbf{x}_{c_i} \cdot \mathbf{W_b}) + \mathbf{t}_{c_i}).
\end{aligned}
\end{equation}

\subsection{History Summarization}
To summarize the users' historical behaviors, we leverage Transformer to process the previously interacted news.
Compared with other sequential models like convolutional neural network (CNN) and recurrent neural network (RNN), Transformer directly captures the correlations between any two steps of events in the sequence, which is effective in many other machine learning tasks. In our model, to obtain the representation of news sequence, we stack the representation of $L$ news articles into a feature tensor $E\in \mathbb{R}^{L\times{d}}$. With $E$ as input, we derive the sequence vector $\mathbf{p}$ by two stacked Transformer layers.

\subsection{Prediction Layer}
Give the sequence vector $\mathbf{p}$, the representation $\mathbf{x}^*$ of candidate news $c^*$ and the user embedding $\mathbf{u}$, we concatenateand and then feed them into a fully-connected layer to estimate the click rate of candidate news $c^*$: 
\begin{equation}
    \hat{y}_{*} = \phi([\mathbf{p}\,\mathbf{x}^*\,\mathbf{u}] \mathbf{W}^{(1)} +\mathbf{b}^{(1)})\mathbf{W}^{(2)} +\mathbf{b}^{(2)},
\end{equation}
where $\mathbf{W}^{(1)}\in\mathbb{R}^{5d\times2d}$, $\mathbf{b}^{(1)}\in\mathbb{R}^{2d}$, $\mathbf{W}^{(2)}\in\mathbb{R}^{2d\times 1}$ and $\mathbf{b}^{(2)}\in\mathbb{R}$ are the parameters of the prediction layer.
Besides, the negative samples set output by dynamic negative sampling layer are combined with positive samples to compute loss. We adopt binary cross-entropy loss function:
\begin{equation}

Besides, the negative samples set output by dynamic negative sampling layer are combined with positive samples to compute loss. We adopt binary cross-entropy loss function:
\begin{equation}
    L = \sum_{c^* \in D^+ \cup S} {{y}_{*}}\log\sigma({\hat{y}_{*}})+ (1-{y}_{*})\log(1-\sigma(\hat{y}_{*})),
\end{equation}
where $y_{*}$ is the training label of $c^*$, $D^{+}$ represents the positive instance set.

